fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    let len = a.len();
    let values_len = values.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        if mask[i] {
            // Use replacement value at i mod values_len
            result.push(values[i % values_len]);
        } else {
            // Use original value
            result.push(a[i]);
        }
    }

    result
}